      chapters: [{ ...review.chapters[0], diagram: "flowchart LR\nB-->C", diagramItemRefs: ["item-2"] }],
    };
    expect(validateGeneratedReview(currentManifest, input)).toMatchObject({ valid: true, duplicateItemRefs: [] });
  });
});

