};

const review = {
  schemaVersion: 1 as const,
  runId: "run-1",
  chapters: [{ id: "chapter-1", order: 1, title: "Explain the change", summary: "The behavior changes coherently.", itemRefs: ["item-1", "item-2"], keyChanges: [] }],
