   281	    const oldStart = Number(coordinates[1]);
   282	    const oldLines = Number(coordinates[2] ?? 1);
   283	    const newStart = Number(coordinates[3]);
   284	    const newLines = Number(coordinates[4] ?? 1);
   285	    const hunkPatch = current.join("\n");
   286	    const ordinal = hunks.length;
   287	    hunks.push({
   288	      id: stableId("item", changedPath.filePath, oldStart, newStart, sha256(hunkPatch)),
