 58	export function diffCounts(file: ReviewFile, item: ReviewItem): { additions: number; deletions: number } {
 59	  if (item.kind === "file") return { additions: file.additions, deletions: file.deletions };
 60	  let additions = 0;
 61	  let deletions = 0;
 62	  for (const line of item.patch.split("\n")) {
 63	    if (line.startsWith("+") && !line.startsWith("+++")) additions += 1;
 64	    if (line.startsWith("-") && !line.startsWith("---")) deletions += 1;
 65	  }
 66	  return { additions, deletions };
 67	}
 68	
 69	export function itemLocationLabel(item: ReviewItem): string {
 70	  if (item.kind === "file") return item.status === "snapshot" ? "snapshot" : item.status === "renamed" ? "path change" : "file change";
 71	  if (item.status === "deleted") return "deleted";
 72	  const line = item.newStart && item.newStart > 0 ? item.newStart : item.oldStart ?? 1;
 73	  return `line ${line}`;
 74	}
 75	
 76	function alphabetic(index: number): string {
 77	  let value = index + 1;
 78	  let label = "";
 79	  while (value > 0) {
 80	    value -= 1;
 81	    label = String.fromCharCode(97 + (value % 26)) + label;
 82	    value = Math.floor(value / 26);
 83	  }
 84	  return label;
 85	}
  1	import type { Chapter, ReviewFile, ReviewItem } from "@diffpanel/core";
  2	import { diffCounts } from "./presentation.js";
