 23	export function chapterItemRefs(chapters: Chapter[], chapterId: string): string[] {
 24	  const byParent = new Map<string, Chapter[]>();
 25	  for (const chapter of chapters) {
 26	    if (chapter.parentId === null) continue;
 27	    const children = byParent.get(chapter.parentId) ?? [];
 28	    children.push(chapter);
 29	    byParent.set(chapter.parentId, children);
 30	  }
 31	  const byId = new Map(chapters.map((chapter) => [chapter.id, chapter] as const));
 32	  const refs: string[] = [];
 33	  const visited = new Set<string>();
 34	  const visit = (id: string): void => {
 35	    if (visited.has(id)) return;
 36	    visited.add(id);
 37	    const chapter = byId.get(id);
 38	    if (!chapter) return;
 39	    refs.push(...chapter.itemRefs);
 40	    for (const child of byParent.get(id) ?? []) visit(child.id);
 41	  };
 42	  visit(chapterId);
 43	  return refs;
 44	}
