 69	export function itemLocationLabel(item: ReviewItem): string {
 70	  if (item.kind === "file") return item.status === "snapshot" ? "snapshot" : item.status === "renamed" ? "path change" : "file change";
 71	  if (item.status === "deleted") return "deleted";
 72	  const line = item.newStart && item.newStart > 0 ? item.newStart : item.oldStart ?? 1;
 73	  return `line ${line}`;
 74	}
