 18	export function groupFiles(matches: ItemMatch[]): FileGroup[] {
 19	  const groups = new Map<string, FileGroup>();
 20	  const seen = new Set<string>();
 21	  for (const { file, item } of matches) {
 22	    if (seen.has(item.id)) continue;
 23	    seen.add(item.id);
 24	    const group = groups.get(file.id) ?? { file, items: [], additions: 0, deletions: 0 };
 25	    group.items.push(item);
 26	    const counts = diffCounts(file, item);
 27	    group.additions += counts.additions;
 28	    group.deletions += counts.deletions;
 29	    groups.set(file.id, group);
 30	  }
 31	  return [...groups.values()].map((group) => ({
 32	    ...group, items: group.items.sort((a, b) => a.ordinal - b.ordinal),
 33	  }));
 34	}
