 12	export function validateGeneratedReview(
 13	  manifestInput: unknown,
 14	  reviewInput: unknown,
 15	): ReviewValidationResult {
 16	  const manifestResult = reviewManifestSchema.safeParse(manifestInput);
 17	  const reviewResult = generatedReviewSchema.safeParse(reviewInput);
 18	  const errors: string[] = [];
 19	
 20	  if (!manifestResult.success) {
 21	    errors.push(...manifestResult.error.issues.map((issue) =>
 22	      `manifest.${issue.path.join(".")}: ${issue.message}`,
 23	    ));
 24	  }
 25	  if (!reviewResult.success) {
 26	    errors.push(...reviewResult.error.issues.map((issue) =>
 27	      `review.${issue.path.join(".")}: ${issue.message}`,
 28	    ));
 29	  }
 30	
 31	  if (!manifestResult.success || !reviewResult.success) {
 32	    return {
 33	      valid: false,
 34	      errors,
 35	      missingItemRefs: [],
 36	      duplicateItemRefs: [],
 37	      extraItemRefs: [],
 38	    };
 39	  }
 40	
 41	  const manifest = manifestResult.data;
 42	  const review = reviewResult.data;
 43	  const visualAssessment = review.diagramAssessment;
 44	  const enforceVisuals = !!manifest.requirements?.diagramAssessment || !!visualAssessment;
 45	  const hasOverview = !!review.prologue.diagram?.trim();
 46	  const hasChapterDiagrams = review.chapters.some((chapter) => !!chapter.diagram?.trim());
 47	  if (enforceVisuals) {
 48	    if (!visualAssessment) errors.push("review requires diagramAssessment for this snapshot");
 49	    else {
 50	      if (!hasOverview && !visualAssessment.overviewOmissionReason) errors.push("provide an overview diagram or overviewOmissionReason");
 51	      if (hasOverview && visualAssessment.overviewOmissionReason) errors.push("overview diagram and overviewOmissionReason are mutually exclusive");
 52	      if (visualAssessment.kind === "architectural" && !hasChapterDiagrams && !visualAssessment.chapterDiagramOmissionReason) {
 53	        errors.push("architectural reviews require focused chapter diagrams or chapterDiagramOmissionReason");
 54	      }
 55	      if (hasChapterDiagrams && visualAssessment.chapterDiagramOmissionReason) errors.push("chapter diagrams and chapterDiagramOmissionReason are mutually exclusive");
 56	    }
 57	    if (hasOverview && !review.prologue.diagramItemRefs?.length) errors.push("prologue diagram requires evidence item refs");
 58	  }
 59	  if (manifest.runId !== review.runId) {
 60	    errors.push(`review.runId ${review.runId} does not match manifest runId ${manifest.runId}`);
 61	  }
 62	
 63	  const chapterIds = new Set<string>();
 64	  const chapterOrders = new Set<number>();
 65	  for (const chapter of review.chapters) {
 66	    if (chapterIds.has(chapter.id)) errors.push(`duplicate chapter id: ${chapter.id}`);
 67	    if (chapterOrders.has(chapter.order)) errors.push(`duplicate chapter order: ${chapter.order}`);
 68	    chapterIds.add(chapter.id);
 69	    chapterOrders.add(chapter.order);
 70	  }
 71	  for (const chapter of review.chapters) {
 72	    if (chapter.parentId === chapter.id) errors.push(`chapter ${chapter.id} cannot be its own parent`);
 73	    if (chapter.parentId && !chapterIds.has(chapter.parentId)) {
 74	      errors.push(`chapter ${chapter.id} has unknown parent ${chapter.parentId}`);
 75	    }
 76	    const ancestry = new Set([chapter.id]);
 77	    let parentId = chapter.parentId;
 78	    while (parentId) {
 79	      if (ancestry.has(parentId)) {
 80	        errors.push(`chapter hierarchy contains a cycle at ${parentId}`);
 81	        break;
 82	      }
 83	      ancestry.add(parentId);
 84	      parentId = review.chapters.find((candidate) => candidate.id === parentId)?.parentId ?? null;
 85	    }
 86	    const hasChildren = review.chapters.some((candidate) => candidate.parentId === chapter.id);
 87	    if (chapter.itemRefs.length === 0 && !hasChildren) {
 88	      errors.push(`chapter ${chapter.id} has no review items or child chapters`);
 89	    }
 90	  }
 91	
 92	  const expected = new Set(manifest.files.flatMap((file) => file.items.map((item) => item.id)));
 93	  const checkDiagramRefs = (label: string, refs: string[] | undefined, allowed: Set<string>): void => {
 94	    const seen = new Set<string>();
 95	    for (const ref of refs ?? []) {
 96	      if (!allowed.has(ref)) errors.push(`${label} diagram references out-of-scope item ${ref}`);
 97	      if (seen.has(ref)) errors.push(`${label} diagram repeats item ${ref}`);
 98	      seen.add(ref);
 99	    }
100	  };
101	  checkDiagramRefs("prologue", review.prologue.diagramItemRefs, expected);
102	  for (const chapter of review.chapters) {
103	    const allowed = new Set<string>();
104	    const visited = new Set<string>();
105	    const collect = (id: string): void => {
106	      if (visited.has(id)) return;
107	      visited.add(id);
108	      for (const candidate of review.chapters) {
109	        if (candidate.id === id) for (const ref of candidate.itemRefs) if (expected.has(ref)) allowed.add(ref);
110	        if (candidate.parentId === id) collect(candidate.id);
111	      }
112	    };
113	    collect(chapter.id);
114	    checkDiagramRefs(`chapter ${chapter.id}`, chapter.diagramItemRefs, allowed);
115	    if (chapter.diagram && !chapter.diagramItemRefs?.length) {
116	      errors.push(`chapter ${chapter.id} diagram requires evidence item refs`);
117	    }
118	  }
119	  const observed = new Map<string, number>();
120	  for (const itemRef of review.chapters.flatMap((chapter) => chapter.itemRefs)) {
121	    observed.set(itemRef, (observed.get(itemRef) ?? 0) + 1);
122	  }
123	
124	  const missingItemRefs = [...expected].filter((id) => !observed.has(id)).sort();
125	  const duplicateItemRefs = [...observed.entries()]
126	    .filter(([, count]) => count > 1)
127	    .map(([id]) => id)
128	    .sort();
129	  const extraItemRefs = [...observed.keys()].filter((id) => !expected.has(id)).sort();
130	
131	  if (missingItemRefs.length > 0) errors.push(`missing item refs: ${missingItemRefs.join(", ")}`);
132	  if (duplicateItemRefs.length > 0) errors.push(`duplicate item refs: ${duplicateItemRefs.join(", ")}`);
133	  if (extraItemRefs.length > 0) errors.push(`unknown item refs: ${extraItemRefs.join(", ")}`);
134	
135	  const files = new Set(manifest.files.map((file) => file.filePath));
136	  for (const chapter of review.chapters) {
137	    for (const change of chapter.keyChanges) {
138	      for (const ref of change.lineRefs) {
139	        if (!files.has(ref.filePath)) {
140	          errors.push(`chapter ${chapter.id} references unknown file ${ref.filePath}`);
141	        }
142	      }
143	    }
144	  }
145	
146	  return {
147	    valid: errors.length === 0,
148	    errors,
149	    missingItemRefs,
150	    duplicateItemRefs,
151	    extraItemRefs,
152	  };
153	}
154	
155	export function assertGeneratedReview(
156	  manifest: ReviewManifest,
157	  reviewInput: unknown,
158	): GeneratedReview {
159	  const result = validateGeneratedReview(manifest, reviewInput);
160	  if (!result.valid) {
161	    throw new Error(`Generated review validation failed:\n${result.errors.join("\n")}`);
162	  }
163	  return generatedReviewSchema.parse(reviewInput);
164	}
