import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Command } from "commander";
import { captureReview, type CaptureRequest } from "@diffpanel/git";
import { DiffpanelStore, defaultDiffpanelHome } from "@diffpanel/storage";

const program = new Command();
program
  .name("diffpanel")
  .description("Prepare, publish, and inspect persistent Diffpanel review runs.")
  .version("0.0.0");

program
  .command("prep")
  .description("Capture an immutable review snapshot and print its receipt path.")
  .argument("[range]", "Git range such as main..feature or main...feature")
  .option("--repository <path>", "Repository path", process.cwd())
  .option("--worktree", "Capture staged, unstaged, and untracked changes")
  .option("--staged", "Capture only staged changes")
  .option("--repo [ref]", "Capture a repository-wide snapshot", false)
  .option("--base <ref>", "Base ref for worktree or staged capture", "HEAD")
  .option("--max-files <count>", "Repository snapshot file limit", parseInteger, 2_000)
  .option("--max-file-bytes <count>", "Maximum bytes captured from one file", parseInteger)
  .option("--max-total-bytes <count>", "Maximum aggregate captured content bytes", parseInteger)
  .option("--max-output-bytes <count>", "Maximum output bytes from each Git subprocess", parseInteger)
  .option("--timeout-ms <count>", "Git subprocess deadline in milliseconds", parseInteger)
  .option("--title <title>", "Display name for this review in the Diffpanel panel")
  .option("--json", "Print the full receipt as JSON")
  .action(async (range: string | undefined, options) => {
    const selected = [Boolean(range), options.worktree, options.staged, Boolean(options.repo)].filter(Boolean);
    if (selected.length > 1) throw new Error("Choose only one of a range, --worktree, --staged, or --repo.");
    const request = toCaptureRequest(range, options);
    const controller = new AbortController();
    const cancel = (): void => controller.abort();
    process.once("SIGINT", cancel);
    const captured = await captureReview(request, {
      signal: controller.signal,
      limits: {
        ...(options.maxFileBytes ? { maxFileBytes: options.maxFileBytes } : {}),
        ...(options.maxTotalBytes ? { maxTotalBytes: options.maxTotalBytes } : {}),
        ...(options.maxOutputBytes ? { maxProcessOutputBytes: options.maxOutputBytes } : {}),
        ...(options.timeoutMs ? { processTimeoutMs: options.timeoutMs } : {}),
      },
    }).finally(() => process.removeListener("SIGINT", cancel));
    const store = await DiffpanelStore.open();
    try {
      const receipt = await store.createPreparedRun(captured, { title: options.title });
      process.stdout.write(options.json ? `${JSON.stringify(receipt, null, 2)}\n` : `${receipt.receiptPath}\n`);
    } finally {
      store.close();
    }
  });

program
  .command("publish")
  .description("Validate and persist generated chapters for a prepared run.")
  .argument("<review-file>", "Generated review JSON file")
  .requiredOption("--run <run-id>", "Prepared run ID")
  .option("--title <title>", "Display name for this review in the Diffpanel panel")
  .option("--json", "Print the published review as JSON")
  .action(async (reviewFile: string, options) => {
    const review = JSON.parse(await readFile(resolve(reviewFile), "utf8"));
    if (options.title) review.title = options.title;
    const store = await DiffpanelStore.open();
    try {
      const published = await store.publish(options.run, review);
      process.stdout.write(options.json
        ? `${JSON.stringify(published, null, 2)}\n`
        : `Published ${published.chapters.length} chapters for ${published.runId}.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("validate")
  .description("Validate generated chapters without publishing them.")
  .argument("<review-file>", "Generated review JSON file")
  .requiredOption("--run <run-id>", "Prepared run ID")
  .action(async (reviewFile: string, options) => {
    const review = JSON.parse(await readFile(resolve(reviewFile), "utf8"));
    const store = await DiffpanelStore.open();
    try {
      const validated = await store.validate(options.run, review);
      const { manifest } = await store.getRun(options.run);
      process.stdout.write(`Valid review: ${validated.chapters.length} chapters cover every item exactly once; ${manifest.files.length} captured files, ${manifest.skipped.length} skipped paths outside coverage.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("list")
  .description("List generated and prepared review runs.")
  .option("--repository <path>", "Only runs for this repository")
  .option("--include-archived", "Include archived review runs")
  .option("--limit <count>", "Maximum runs to return (1-200)", parseInteger, 50)
  .option("--cursor <cursor>", "Continue a prior paginated listing")
  .option("--page", "Return runs with the next cursor")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const page = store.listRunsPage({
        repositoryRoot: options.repository ? resolve(options.repository) : undefined,
        includeArchived: options.includeArchived,
        limit: options.limit,
        cursor: options.cursor,
      });
      if (options.json) {
        process.stdout.write(`${JSON.stringify(options.page ? page : page.runs, null, 2)}\n`);
        return;
      }
      for (const run of page.runs) {
        process.stdout.write(`${run.runId}\t${run.status}\t${run.repositoryName}\t${run.reviewTitle}\t${run.chapterCount} chapters\n`);
      }
      if (page.nextCursor) process.stdout.write(`Next cursor: ${page.nextCursor}\n`);
    } finally {
      store.close();
    }
  });

program
  .command("title")
  .description("Set or clear the display name for a review run.")
  .argument("<run-id>", "Review run ID")
  .argument("[title]", "Display name shown in the Diffpanel panel")
  .option("--clear", "Revert to the default git-scope label")
  .action(async (runId: string, title: string | undefined, options) => {
    if (Boolean(options.clear) === Boolean(title)) {
      throw new Error("Pass a title or --clear.");
    }
    const store = await DiffpanelStore.open();
    try {
      const summary = store.setReviewTitle(runId, options.clear ? null : title!);
      process.stdout.write(options.clear
        ? `Cleared title for ${runId}; now ${summary.reviewTitle}.\n`
        : `Renamed ${runId} to ${summary.reviewTitle}.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("archive")
  .description("Archive a review run so it is hidden from default listings.")
  .argument("<run-id>", "Review run ID")
  .action(async (runId: string) => {
    const store = await DiffpanelStore.open();
    try {
      store.setArchived(runId, true);
      process.stdout.write(`Archived ${runId}.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("unarchive")
  .description("Restore an archived review run to default listings.")
  .argument("<run-id>", "Review run ID")
  .action(async (runId: string) => {
    const store = await DiffpanelStore.open();
    try {
      store.setArchived(runId, false);
      process.stdout.write(`Restored ${runId}.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("show")
  .description("Read a complete review run.")
  .argument("<run-id>", "Review run ID")
  .option("--json", "Print JSON", true)
  .action(async (runId: string) => {
    const store = await DiffpanelStore.open();
    try {
      process.stdout.write(`${JSON.stringify(await store.getRun(runId), null, 2)}\n`);
    } finally {
      store.close();
    }
  });

program
  .command("content")
  .description("Read immutable file content for an editor diff.")
  .argument("<run-id>", "Review run ID")
  .argument("<file-id>", "Manifest file ID")
  .argument("<side>", "before or after")
  .action(async (runId: string, fileId: string, side: string) => {
    if (side !== "before" && side !== "after") throw new Error("Content side must be before or after.");
    const store = await DiffpanelStore.open();
    try {
      const content = await store.getFileContent(runId, fileId, side);
      if (content) process.stdout.write(content);
    } finally {
      store.close();
    }
  });

program
  .command("prune")
  .description("Delete expired runs and garbage-collect only unreferenced blobs.")
  .option("--repository <path>", "Only apply retention to one repository")
  .option("--older-than-days <count>", "Delete eligible runs older than this many days", parseNonNegativeInteger, 90)
  .option("--keep-latest <count>", "Always retain this many latest runs per repository", parseNonNegativeInteger, 50)
  .option("--include-active", "Allow prepared and ready, non-archived runs to expire")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const result = await store.applyRetention({
        repositoryRoot: options.repository ? resolve(options.repository) : undefined,
        olderThan: new Date(Date.now() - options.olderThanDays * 24 * 60 * 60 * 1_000),
        keepLatest: options.keepLatest,
        archivedOnly: !options.includeActive,
      });
      process.stdout.write(options.json
        ? `${JSON.stringify(result, null, 2)}\n`
        : `Deleted ${result.deletedRunIds.length} runs and ${result.deletedBlobCount} unreferenced blobs; retained ${result.retainedRunCount} runs.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("doctor")
  .description("Print the local Diffpanel installation and storage configuration.")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const report = {
        ok: true,
        node: process.version,
        platform: process.platform,
        home: defaultDiffpanelHome(),
        databasePath: store.databasePath,
        runs: store.listRuns(undefined, true).length,
        recovery: store.lastRecoveryReport,
      };
      process.stdout.write(options.json
        ? `${JSON.stringify(report, null, 2)}\n`
        : Object.entries(report).map(([key, value]) => `${key}: ${value}`).join("\n") + "\n");
    } finally {
      store.close();
    }
  });

program.parseAsync(process.argv).catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`diffpanel: ${message}\n`);
  process.exitCode = 1;
});

function parseInteger(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed <= 0) throw new Error(`Expected a positive integer, received '${value}'.`);
  return parsed;
}

function parseNonNegativeInteger(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed < 0) throw new Error(`Expected a non-negative integer, received '${value}'.`);
  return parsed;
}

function toCaptureRequest(range: string | undefined, options: {
  repository: string;
  worktree?: boolean;
  staged?: boolean;
  repo?: boolean | string;
  base: string;
  maxFiles: number;
}): CaptureRequest {
  const repository = resolve(options.repository);
  if (range) return { type: "range", repository, expression: range };
  if (options.worktree) return { type: "worktree", repository, baseRef: options.base };
  if (options.staged) return { type: "staged", repository, baseRef: options.base };
  if (options.repo) {
    return {
      type: "repository",
      repository,
      ref: typeof options.repo === "string" ? options.repo : "HEAD",
      maxFiles: options.maxFiles,
    };
  }
  return { type: "auto", repository };
}
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { tmpdir } from "node:os";
import { afterEach, describe, expect, it } from "vitest";
import { runProcess } from "@diffpanel/git";
import type { ReviewManifest } from "diffpanel";

const temporaryDirectories: string[] = [];

afterEach(async () => {
  await Promise.all(temporaryDirectories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

async function runCli(args: string[], home: string, cwd: string): Promise<string> {
  const entry = resolve("dist/index.js");
  const result = await new Promise<{ stdout: string; stderr: string; code: number }>((resolvePromise, reject) => {
    const child = runProcess(process.execPath, [entry, ...args], cwd);
    child.then((value) => resolvePromise({
      stdout: value.stdout.toString("utf8"),
      stderr: value.stderr.toString("utf8"),
      code: value.exitCode,
    })).catch(reject);
  });
  expect(result.code, result.stderr).toBe(0);
  return result.stdout;
}

describe("diffpanel CLI", () => {
  it("prepares, validates, publishes, lists, and reads immutable content", async () => {
    const repository = await mkdtemp(join(tmpdir(), "diffpanel-cli-repo-"));
    const home = await mkdtemp(join(tmpdir(), "diffpanel-cli-home-"));
    temporaryDirectories.push(repository, home);
    await runProcess("git", ["init", "-b", "main"], repository);
    await runProcess("git", ["config", "user.email", "diffpanel@example.com"], repository);
    await runProcess("git", ["config", "user.name", "Diffpanel Test"], repository);
    await writeFile(join(repository, "example.ts"), "export const value = 1;\n");
    await runProcess("git", ["add", "example.ts"], repository);
    await runProcess("git", ["commit", "-m", "initial"], repository);
    await writeFile(join(repository, "example.ts"), "export const value = 2;\n");

    const previousHome = process.env.DIFFPANEL_HOME;
    process.env.DIFFPANEL_HOME = home;
    try {
      const receipt = JSON.parse(await runCli(["prep", "--worktree", "--repository", repository, "--title", "Worktree review", "--json"], home, repository)) as {
        runId: string;
        manifestPath: string;
        title: string;
        reviewTitle: string;
      };
      expect(receipt.title).toBe("Worktree review");
      expect(receipt.reviewTitle).toBe("Worktree review");
      const manifest = JSON.parse(await readFile(receipt.manifestPath, "utf8")) as ReviewManifest;
      const itemRefs = manifest.files.flatMap((file) => file.items.map((item) => item.id));
      const reviewPath = join(home, "review.json");
      await writeFile(reviewPath, JSON.stringify({
        schemaVersion: 1,
        runId: receipt.runId,
        generator: "e2e",
        diagramAssessment: { kind: "other", reasoning: "One constant changes.", overviewOmissionReason: "No structural or execution flow change." },
        chapters: [{
          id: "chapter-1",
          parentId: null,
          order: 1,
          title: "Update the exported value",
          summary: "The exported value changes while preserving its public shape.",
          itemRefs,
          keyChanges: [],
        }],
        prologue: {
          motivation: null,
          outcome: "Consumers now receive the updated value.",
          diagram: null,
          keyChanges: [{ summary: "Consumers receive the revised exported value", description: "The module retains its existing export while changing the returned constant." }],
          focusAreas: [{ type: "testing-gap", severity: "info", title: "Consumer expectation coverage", description: "The exported value changed without a test update; confirm consumers expect the new value.", locations: ["example.ts"] }],
          complexity: { level: "low", reasoning: "One value changed in one file." },
        },
      }));

      expect(await runCli(["validate", reviewPath, "--run", receipt.runId], home, repository)).toContain("cover every item exactly once");
      expect(await runCli(["publish", reviewPath, "--run", receipt.runId, "--title", "Update exported value"], home, repository)).toContain("Published 1 chapters");
      const runs = JSON.parse(await runCli(["list", "--json"], home, repository)) as Array<{ status: string; runId: string; reviewTitle: string }>;
      expect(runs).toEqual([expect.objectContaining({ runId: receipt.runId, status: "ready", reviewTitle: "Update exported value" })]);
      expect(await runCli(["title", receipt.runId, "Named review"], home, repository)).toContain("Renamed");
      expect(JSON.parse(await runCli(["list", "--json"], home, repository))).toEqual([
        expect.objectContaining({ runId: receipt.runId, reviewTitle: "Named review" }),
      ]);
      expect(await runCli(["title", receipt.runId, "--clear"], home, repository)).toContain("Working tree");
      expect(await runCli(["archive", receipt.runId], home, repository)).toContain(`Archived ${receipt.runId}`);
      expect(JSON.parse(await runCli(["list", "--json"], home, repository))).toEqual([]);
      const archivedRuns = JSON.parse(await runCli(["list", "--include-archived", "--json"], home, repository)) as Array<{ archivedAt: string | null }>;
      expect(archivedRuns[0]?.archivedAt).not.toBeNull();
      expect(await runCli(["unarchive", receipt.runId], home, repository)).toContain(`Restored ${receipt.runId}`);
      const file = manifest.files[0]!;
      expect(await runCli(["content", receipt.runId, file.id, "after"], home, repository)).toContain("value = 2");
    } finally {
      if (previousHome === undefined) delete process.env.DIFFPANEL_HOME;
      else process.env.DIFFPANEL_HOME = previousHome;
    }
  });
});
import { cp, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import process from "node:process";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const appDirectory = path.resolve(scriptDirectory, "..");
const stagingDirectory = await mkdtemp(path.join(tmpdir(), "diffpanel-vsix-"));

try {
  const manifest = JSON.parse(await readFile(path.join(appDirectory, "package.json"), "utf8"));
  manifest.name = "diffpanel";
  delete manifest.private;

  await writeFile(path.join(stagingDirectory, "package.json"), `${JSON.stringify(manifest, null, 2)}\n`);
  for (const entry of ["README.md", "CHANGELOG.md", "dist", "media"]) {
    await cp(path.join(appDirectory, entry), path.join(stagingDirectory, entry), { recursive: true });
  }

  const binary = path.join(appDirectory, "node_modules", ".bin", process.platform === "win32" ? "vsce.cmd" : "vsce");
  const output = path.join(appDirectory, `diffpanel-${manifest.version}.vsix`);
  await run(binary, ["package", "--no-dependencies", "--allow-missing-repository", "--out", output], stagingDirectory);
  process.stdout.write(`${output}\n`);
} finally {
  await rm(stagingDirectory, { recursive: true, force: true });
}

async function run(command, args, cwd) {
  await new Promise((resolve, reject) => {
    const child = spawn(command, args, { cwd, stdio: "inherit" });
    child.on("error", reject);
    child.on("close", (code) => code === 0 ? resolve() : reject(new Error(`${command} exited with ${code ?? -1}`)));
  });
}

