import { spawn, type ChildProcess } from "node:child_process";

export interface ProcessResult {
  stdout: Buffer;
  stderr: Buffer;
  exitCode: number;
}

export interface ProcessOptions {
  acceptedExitCodes?: readonly number[];
  signal?: AbortSignal;
  timeoutMs?: number;
  maxOutputBytes?: number;
}

export const DEFAULT_PROCESS_TIMEOUT_MS = 30_000;
export const DEFAULT_MAX_PROCESS_OUTPUT_BYTES = 16 * 1024 * 1024;

export async function runProcess(
  command: string,
  args: string[],
  cwd: string,
  acceptedExitCodesOrOptions: readonly number[] | ProcessOptions = [0],
): Promise<ProcessResult> {
  const options: ProcessOptions = Array.isArray(acceptedExitCodesOrOptions)
    ? { acceptedExitCodes: acceptedExitCodesOrOptions }
    : acceptedExitCodesOrOptions as ProcessOptions;
  const acceptedExitCodes = options.acceptedExitCodes ?? [0];
  const timeoutMs = options.timeoutMs ?? DEFAULT_PROCESS_TIMEOUT_MS;
  const maxOutputBytes = options.maxOutputBytes ?? DEFAULT_MAX_PROCESS_OUTPUT_BYTES;

  if (options.signal?.aborted) throw abortError(command);
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs <= 0) throw new Error("Process timeout must be a positive integer.");
  if (!Number.isSafeInteger(maxOutputBytes) || maxOutputBytes <= 0) throw new Error("Process output limit must be a positive integer.");

  return await new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd,
      detached: process.platform !== "win32",
      env: { ...process.env, GIT_OPTIONAL_LOCKS: "0" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    let outputBytes = 0;
    let terminalError: Error | null = null;
    let settled = false;
    let timeout: NodeJS.Timeout | undefined;

    const finish = (error: Error | null, result?: ProcessResult): void => {
      if (settled) return;
      settled = true;
      if (timeout) clearTimeout(timeout);
      options.signal?.removeEventListener("abort", onAbort);
      if (error) reject(error);
      else resolve(result!);
    };

    const terminate = (error: Error): void => {
      if (terminalError) return;
      terminalError = error;
      terminateProcess(child, "SIGTERM");
      const forceTimer = setTimeout(() => terminateProcess(child, "SIGKILL"), 1_000);
      forceTimer.unref();
    };

    const collect = (target: Buffer[], chunk: Buffer): void => {
      outputBytes += chunk.length;
      if (outputBytes > maxOutputBytes) {
        terminate(new Error(`${command} exceeded the ${maxOutputBytes}-byte output limit.`));
        return;
      }
      target.push(chunk);
    };

    const onAbort = (): void => terminate(abortError(command));

    child.stdout.on("data", (chunk: Buffer) => collect(stdout, chunk));
    child.stderr.on("data", (chunk: Buffer) => collect(stderr, chunk));
    child.on("error", (error) => finish(error));
    child.on("close", (exitCode) => {
      if (terminalError) {
        finish(terminalError);
        return;
      }
      const result = {
        stdout: Buffer.concat(stdout),
        stderr: Buffer.concat(stderr),
        exitCode: exitCode ?? -1,
      };
      if (!acceptedExitCodes.includes(result.exitCode)) {
        finish(new Error(
          `${command} ${args.join(" ")} failed (${result.exitCode}): ${result.stderr.toString("utf8").trim()}`,
        ));
        return;
      }
      finish(null, result);
    });

    options.signal?.addEventListener("abort", onAbort, { once: true });
    timeout = setTimeout(
      () => terminate(new Error(`${command} timed out after ${timeoutMs}ms.`)),
      timeoutMs,
    );
    timeout.unref();
  });
}

function abortError(command: string): Error {
  return new Error(`${command} was cancelled.`);
}

function terminateProcess(child: ChildProcess, signal: NodeJS.Signals): void {
  if (child.exitCode !== null || child.signalCode !== null) return;
  try {
    if (process.platform !== "win32" && child.pid) process.kill(-child.pid, signal);
    else child.kill(signal);
  } catch {
    child.kill(signal);
  }
}

export async function gitBuffer(
  cwd: string,
  args: string[],
  acceptedExitCodesOrOptions: readonly number[] | ProcessOptions = [0],
): Promise<Buffer> {
  return (await runProcess("git", args, cwd, acceptedExitCodesOrOptions)).stdout;
}

export async function gitText(
  cwd: string,
  args: string[],
  acceptedExitCodesOrOptions: readonly number[] | ProcessOptions = [0],
): Promise<string> {
  return (await gitBuffer(cwd, args, acceptedExitCodesOrOptions)).toString("utf8").trim();
}
import { spawn } from "node:child_process";
import * as vscode from "vscode";
import type { RunSummary, StoredRun } from "@diffpanel/storage";
import { resolveInvocation, type Invocation } from "./invocation.js";

export class DiffpanelCli {
  private readonly output = vscode.window.createOutputChannel("Diffpanel");

  constructor(private readonly extensionPath: string) {}

  dispose(): void {
    this.output.dispose();
  }

  async list(includeArchived = false): Promise<RunSummary[]> {
    return JSON.parse(await this.execute(["list", ...(includeArchived ? ["--include-archived"] : []), "--json"])) as RunSummary[];
  }

  async show(runId: string): Promise<StoredRun> {
    return JSON.parse(await this.execute(["show", runId, "--json"])) as StoredRun;
  }

  async content(runId: string, fileId: string, side: "before" | "after"): Promise<string> {
    return await this.execute(["content", runId, fileId, side]);
  }

  async setArchived(runId: string, archived: boolean): Promise<void> {
    await this.execute([archived ? "archive" : "unarchive", runId]);
  }

  async setTitle(runId: string, title: string): Promise<void> {
    await this.execute(["title", runId, title]);
  }

  private async execute(args: string[]): Promise<string> {
    const configuration = vscode.workspace.getConfiguration("diffpanel");
    const invocation = resolveInvocation({
      extensionPath: this.extensionPath,
      configuredCliPath: configuration.get<string>("cliPath", ""),
      configuredNodePath: configuration.get<string>("nodePath", ""),
    });
    const home = configuration.get<string>("home", "").trim();
    const commandArgs = [...invocation.leadingArgs, ...args];
    this.output.appendLine(`> ${invocation.command} ${commandArgs.join(" ")}`);

    return await new Promise((resolve, reject) => {
      const child = spawn(invocation.command, commandArgs, {
        cwd: vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.extensionPath,
        env: { ...process.env, ...(home ? { DIFFPANEL_HOME: home } : {}) },
        stdio: ["ignore", "pipe", "pipe"],
        windowsHide: true,
      });
      const stdout: Buffer[] = [];
      const stderr: Buffer[] = [];
      child.stdout.on("data", (chunk: Buffer) => stdout.push(chunk));
      child.stderr.on("data", (chunk: Buffer) => stderr.push(chunk));
      child.on("error", (error) => reject(this.commandError(invocation, error.message)));
      child.on("close", (code) => {
        const output = Buffer.concat(stdout).toString("utf8");
        const errorOutput = Buffer.concat(stderr).toString("utf8").trim();
        if (errorOutput) this.output.appendLine(errorOutput);
        if (code !== 0) {
          reject(this.commandError(invocation, errorOutput || `Exited with code ${code}.`));
          return;
        }
        resolve(output);
      });
    });
  }

  private commandError(invocation: Invocation, detail: string): Error {
    const message = `Could not run Diffpanel CLI (${invocation.displayPath}): ${detail}`;
    this.output.appendLine(message);
    return new Error(message);
  }
}
#!/usr/bin/env node
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Command } from "commander";
import { captureReview, type CaptureRequest } from "@diffpanel/git";
import { DiffpanelStore, defaultDiffpanelHome } from "@diffpanel/storage";

const program = new Command();
program
  .name("diffpanel")
  .description("Prepare, publish, and inspect persistent Diffpanel review runs.")
  .version("0.0.0");

program
  .command("prep")
  .description("Capture an immutable review snapshot and print its receipt path.")
  .argument("[range]", "Git range such as main..feature or main...feature")
  .option("--repository <path>", "Repository path", process.cwd())
  .option("--worktree", "Capture staged, unstaged, and untracked changes")
  .option("--staged", "Capture only staged changes")
  .option("--repo [ref]", "Capture a repository-wide snapshot", false)
  .option("--base <ref>", "Base ref for worktree or staged capture", "HEAD")
  .option("--max-files <count>", "Repository snapshot file limit", parseInteger, 2_000)
  .option("--max-file-bytes <count>", "Maximum bytes captured from one file", parseInteger)
  .option("--max-total-bytes <count>", "Maximum aggregate captured content bytes", parseInteger)
  .option("--max-output-bytes <count>", "Maximum output bytes from each Git subprocess", parseInteger)
  .option("--timeout-ms <count>", "Git subprocess deadline in milliseconds", parseInteger)
  .option("--title <title>", "Display name for this review in the Diffpanel panel")
  .option("--json", "Print the full receipt as JSON")
  .action(async (range: string | undefined, options) => {
    const selected = [Boolean(range), options.worktree, options.staged, Boolean(options.repo)].filter(Boolean);
    if (selected.length > 1) throw new Error("Choose only one of a range, --worktree, --staged, or --repo.");
    const request = toCaptureRequest(range, options);
    const controller = new AbortController();
    const cancel = (): void => controller.abort();
    process.once("SIGINT", cancel);
    const captured = await captureReview(request, {
      signal: controller.signal,
      limits: {
        ...(options.maxFileBytes ? { maxFileBytes: options.maxFileBytes } : {}),
        ...(options.maxTotalBytes ? { maxTotalBytes: options.maxTotalBytes } : {}),
        ...(options.maxOutputBytes ? { maxProcessOutputBytes: options.maxOutputBytes } : {}),
        ...(options.timeoutMs ? { processTimeoutMs: options.timeoutMs } : {}),
      },
    }).finally(() => process.removeListener("SIGINT", cancel));
    const store = await DiffpanelStore.open();
    try {
      const receipt = await store.createPreparedRun(captured, { title: options.title });
      process.stdout.write(options.json ? `${JSON.stringify(receipt, null, 2)}\n` : `${receipt.receiptPath}\n`);
    } finally {
      store.close();
    }
  });

program
  .command("publish")
  .description("Validate and persist generated chapters for a prepared run.")
  .argument("<review-file>", "Generated review JSON file")
  .requiredOption("--run <run-id>", "Prepared run ID")
  .option("--title <title>", "Display name for this review in the Diffpanel panel")
  .option("--json", "Print the published review as JSON")
  .action(async (reviewFile: string, options) => {
    const review = JSON.parse(await readFile(resolve(reviewFile), "utf8"));
    if (options.title) review.title = options.title;
    const store = await DiffpanelStore.open();
    try {
      const published = await store.publish(options.run, review);
      process.stdout.write(options.json
        ? `${JSON.stringify(published, null, 2)}\n`
        : `Published ${published.chapters.length} chapters for ${published.runId}.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("validate")
  .description("Validate generated chapters without publishing them.")
  .argument("<review-file>", "Generated review JSON file")
  .requiredOption("--run <run-id>", "Prepared run ID")
  .action(async (reviewFile: string, options) => {
    const review = JSON.parse(await readFile(resolve(reviewFile), "utf8"));
    const store = await DiffpanelStore.open();
    try {
      const validated = await store.validate(options.run, review);
      const { manifest } = await store.getRun(options.run);
      process.stdout.write(`Valid review: ${validated.chapters.length} chapters cover every item exactly once; ${manifest.files.length} captured files, ${manifest.skipped.length} skipped paths outside coverage.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("list")
  .description("List generated and prepared review runs.")
  .option("--repository <path>", "Only runs for this repository")
  .option("--include-archived", "Include archived review runs")
  .option("--limit <count>", "Maximum runs to return (1-200)", parseInteger, 50)
  .option("--cursor <cursor>", "Continue a prior paginated listing")
  .option("--page", "Return runs with the next cursor")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const page = store.listRunsPage({
        repositoryRoot: options.repository ? resolve(options.repository) : undefined,
        includeArchived: options.includeArchived,
        limit: options.limit,
        cursor: options.cursor,
      });
      if (options.json) {
        process.stdout.write(`${JSON.stringify(options.page ? page : page.runs, null, 2)}\n`);
        return;
      }
      for (const run of page.runs) {
        process.stdout.write(`${run.runId}\t${run.status}\t${run.repositoryName}\t${run.reviewTitle}\t${run.chapterCount} chapters\n`);
      }
      if (page.nextCursor) process.stdout.write(`Next cursor: ${page.nextCursor}\n`);
    } finally {
      store.close();
    }
  });

program
  .command("title")
