  static async open(home = defaultDiffpanelHome()): Promise<DiffpanelStore> {
    await mkdir(join(home, "blobs"), { recursive: true });
    await mkdir(join(home, "runs"), { recursive: true });
    const databasePath = resolveDatabasePath(home);
