program
  .command("prune")
  .description("Delete expired runs and garbage-collect only unreferenced blobs.")
  .option("--repository <path>", "Only apply retention to one repository")
  .option("--older-than-days <count>", "Delete eligible runs older than this many days", parseNonNegativeInteger, 90)
  .option("--keep-latest <count>", "Always retain this many latest runs per repository", parseNonNegativeInteger, 50)
  .option("--include-active", "Allow prepared and ready, non-archived runs to expire")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const result = await store.applyRetention({
        repositoryRoot: options.repository ? resolve(options.repository) : undefined,
        olderThan: new Date(Date.now() - options.olderThanDays * 24 * 60 * 60 * 1_000),
        keepLatest: options.keepLatest,
        archivedOnly: !options.includeActive,
      });
      process.stdout.write(options.json
        ? `${JSON.stringify(result, null, 2)}\n`
        : `Deleted ${result.deletedRunIds.length} runs and ${result.deletedBlobCount} unreferenced blobs; retained ${result.retainedRunCount} runs.\n`);
    } finally {
      store.close();
    }
  });

program
  .command("doctor")
  .description("Print the local Diffpanel installation and storage configuration.")
  .option("--json", "Print JSON")
  .action(async (options) => {
    const store = await DiffpanelStore.open();
    try {
      const report = {
        ok: true,
        node: process.version,
        platform: process.platform,
        home: defaultDiffpanelHome(),
        databasePath: store.databasePath,
        runs: store.listRuns(undefined, true).length,
        recovery: store.lastRecoveryReport,
      };
      process.stdout.write(options.json
        ? `${JSON.stringify(report, null, 2)}\n`
        : Object.entries(report).map(([key, value]) => `${key}: ${value}`).join("\n") + "\n");
    } finally {
      store.close();
    }
  });

program.parseAsync(process.argv).catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`diffpanel: ${message}\n`);
  process.exitCode = 1;
});

function parseInteger(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed <= 0) throw new Error(`Expected a positive integer, received '${value}'.`);
  return parsed;
}

function parseNonNegativeInteger(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed < 0) throw new Error(`Expected a non-negative integer, received '${value}'.`);
  return parsed;
}

function toCaptureRequest(range: string | undefined, options: {
  repository: string;
  worktree?: boolean;
  staged?: boolean;
  repo?: boolean | string;
  base: string;
  maxFiles: number;
}): CaptureRequest {
  const repository = resolve(options.repository);
  if (range) return { type: "range", repository, expression: range };
  if (options.worktree) return { type: "worktree", repository, baseRef: options.base };
  if (options.staged) return { type: "staged", repository, baseRef: options.base };
  if (options.repo) {
    return {
      type: "repository",
      repository,
      ref: typeof options.repo === "string" ? options.repo : "HEAD",
      maxFiles: options.maxFiles,
    };
  }
  return { type: "auto", repository };
}
import { spawn } from "node:child_process";
import * as vscode from "vscode";
import type { RunSummary, StoredRun } from "@diffpanel/storage";
import { resolveInvocation, type Invocation } from "./invocation.js";

export class DiffpanelCli {
  private readonly output = vscode.window.createOutputChannel("Diffpanel");

  constructor(private readonly extensionPath: string) {}

  dispose(): void {
    this.output.dispose();
  }

  async list(includeArchived = false): Promise<RunSummary[]> {
    return JSON.parse(await this.execute(["list", ...(includeArchived ? ["--include-archived"] : []), "--json"])) as RunSummary[];
  }

  async show(runId: string): Promise<StoredRun> {
    return JSON.parse(await this.execute(["show", runId, "--json"])) as StoredRun;
  }

  async content(runId: string, fileId: string, side: "before" | "after"): Promise<string> {
    return await this.execute(["content", runId, fileId, side]);
  }

  async setArchived(runId: string, archived: boolean): Promise<void> {
    await this.execute([archived ? "archive" : "unarchive", runId]);
  }

  async setTitle(runId: string, title: string): Promise<void> {
    await this.execute(["title", runId, title]);
  }

  private async execute(args: string[]): Promise<string> {
    const configuration = vscode.workspace.getConfiguration("diffpanel");
    const invocation = resolveInvocation({
      extensionPath: this.extensionPath,
      configuredCliPath: configuration.get<string>("cliPath", ""),
      configuredNodePath: configuration.get<string>("nodePath", ""),
    });
    const home = configuration.get<string>("home", "").trim();
    const commandArgs = [...invocation.leadingArgs, ...args];
    this.output.appendLine(`> ${invocation.command} ${commandArgs.join(" ")}`);

    return await new Promise((resolve, reject) => {
      const child = spawn(invocation.command, commandArgs, {
        cwd: vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? this.extensionPath,
        env: { ...process.env, ...(home ? { DIFFPANEL_HOME: home } : {}) },
        stdio: ["ignore", "pipe", "pipe"],
        windowsHide: true,
      });
      const stdout: Buffer[] = [];
      const stderr: Buffer[] = [];
      child.stdout.on("data", (chunk: Buffer) => stdout.push(chunk));
      child.stderr.on("data", (chunk: Buffer) => stderr.push(chunk));
      child.on("error", (error) => reject(this.commandError(invocation, error.message)));
      child.on("close", (code) => {
        const output = Buffer.concat(stdout).toString("utf8");
        const errorOutput = Buffer.concat(stderr).toString("utf8").trim();
        if (errorOutput) this.output.appendLine(errorOutput);
        if (code !== 0) {
          reject(this.commandError(invocation, errorOutput || `Exited with code ${code}.`));
          return;
        }
        resolve(output);
      });
    });
  }

  private commandError(invocation: Invocation, detail: string): Error {
    const message = `Could not run Diffpanel CLI (${invocation.displayPath}): ${detail}`;
    this.output.appendLine(message);
    return new Error(message);
  }
}
name: Publish tagged package

on:
  push:
    tags:
      - '*-v*.*.*'
  workflow_dispatch:
    inputs:
      release_tag:
        description: 'Existing release tag in the form <package-slug>-v<version>'
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: publish-${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}
  cancel-in-progress: false

jobs:
  publish:
    runs-on: ubuntu-latest
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}

    steps:
      - name: Checkout release tag
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          ref: ${{ env.RELEASE_TAG }}

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 22.13.0
          registry-url: https://registry.npmjs.org

      - name: Resolve publish target
        id: resolve
        run: node ./scripts/resolve-release-tag.mjs "${RELEASE_TAG}"

      - name: Install package dependencies
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        run: npm install --workspaces=false --package-lock=false

      - name: Build package
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        run: npm run build

      - name: Test package
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        run: npm test

      - name: Pack package
        id: pack
        working-directory: ${{ steps.resolve.outputs.pkg_path }}
        shell: bash
        run: |
          set -euo pipefail
          pack_dir="${RUNNER_TEMP}/diffpanel-pack"
          mkdir -p "${pack_dir}"
          npm pack --pack-destination "${pack_dir}" --json
          mapfile -t tarballs < <(find "${pack_dir}" -maxdepth 1 -type f -name '*.tgz' -print)
          if [[ ${#tarballs[@]} -ne 1 ]]; then
            echo "Expected exactly one package tarball, found ${#tarballs[@]}" >&2
            exit 1
          fi
          echo "tarball=${tarballs[0]}" >> "${GITHUB_OUTPUT}"

      - name: Verify clean external install
        shell: bash
        run: |
          set -euo pipefail
          fixture_dir="$(mktemp -d)"
          cd "${fixture_dir}"
          npm init --yes >/dev/null
          npm install --package-lock=false "${{ steps.pack.outputs.tarball }}"
          node --input-type=module --eval 'await import(process.argv[1])' "${{ steps.resolve.outputs.pkg_name }}"

      - name: Publish package
        run: npm publish "${{ steps.pack.outputs.tarball }}" --access public
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}
import { appendFile, readFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repoRoot = path.resolve(__dirname, '..');
const releasePackagesPath = path.join(repoRoot, 'release-packages.json');
const tagPattern = /^(?<slug>[a-z0-9][a-z0-9-]*)-v(?<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)$/;

function fail(message) {
  console.error(message);
  process.exit(1);
}

async function loadReleaseTargets() {
  const raw = await readFile(releasePackagesPath, 'utf8');
  const releasePackages = JSON.parse(raw);

  if (!Array.isArray(releasePackages)) {
    fail(`Expected ${path.relative(repoRoot, releasePackagesPath)} to contain an array`);
  }

  const targets = [];
  const slugs = new Set();

  for (const entry of releasePackages) {
    if (!entry?.slug || !entry?.path || !entry?.name) {
      fail(`Invalid release target entry in ${path.relative(repoRoot, releasePackagesPath)}: ${JSON.stringify(entry)}`);
    }

    if (slugs.has(entry.slug)) {
      fail(`Duplicate release target slug: ${entry.slug}`);
    }

    const packagePath = path.resolve(repoRoot, entry.path);
    const relativePackagePath = path.relative(repoRoot, packagePath);

    if (relativePackagePath.startsWith('..') || path.isAbsolute(relativePackagePath)) {
      fail(`Release target ${entry.slug} resolves outside the repository: ${entry.path}`);
    }

    slugs.add(entry.slug);
    targets.push({
      slug: entry.slug,
      name: entry.name,
      path: relativePackagePath,
    });
  }

  return targets;
}

async function writeOutputs(outputs) {
  if (!process.env.GITHUB_OUTPUT) {
    return;
  }

  const lines = Object.entries(outputs).map(([key, value]) => `${key}=${value}`);
  await appendFile(process.env.GITHUB_OUTPUT, `${lines.join('\n')}\n`);
}

const tag = process.argv[2] ?? process.env.GITHUB_REF_NAME;

if (!tag) {
  fail('Expected a release tag argument or GITHUB_REF_NAME');
}

const match = tag.match(tagPattern);

if (!match?.groups) {
  fail(`Unsupported tag format: ${tag}. Expected <package-slug>-v<version>.`);
}

const { slug, version } = match.groups;
const releaseTargets = await loadReleaseTargets();
const target = releaseTargets.find((candidate) => candidate.slug === slug);

if (!target) {
  const supportedSlugs = releaseTargets.map((candidate) => candidate.slug).join(', ');
  fail(`No publishable workspace found for slug "${slug}". Supported slugs: ${supportedSlugs}`);
}

const packageJsonFile = path.join(repoRoot, target.path, 'package.json');
const packageJson = JSON.parse(await readFile(packageJsonFile, 'utf8'));

if (packageJson.name !== target.name) {
  fail(
    `Release target ${target.slug} expected ${target.name} at ${target.path}/package.json, found ${packageJson.name ?? 'undefined'}`,
  );
}

if (packageJson.private) {
  fail(`Release target ${target.slug} is private in ${target.path}/package.json`);
}

if (packageJson.version !== version) {
  fail(`Tag version ${version} does not match ${target.name}@${packageJson.version} in ${target.path}/package.json`);
}

await writeOutputs({
  pkg_slug: target.slug,
  pkg_name: target.name,
  pkg_version: packageJson.version,
  pkg_path: target.path,
});

console.log(
  JSON.stringify(
    {
      tag,
      slug: target.slug,
      name: target.name,
      version: packageJson.version,
      path: target.path,
    },
    null,
    2,
  ),
);
