    97	async function resolveScope(
    98	  repositoryRoot: string,
    99	  request: Exclude<CaptureRequest, { type: "auto" | "repository" }>,
   100	  processOptions: ProcessOptions,
   101	): Promise<ChangedScope> {
   102	  if (request.type === "worktree" || request.type === "staged") {
   103	    const baseRef = request.baseRef ?? "HEAD";
   104	    validateRef(baseRef);
   105	    const baseSha = await gitText(repositoryRoot, ["rev-parse", "--verify", baseRef], processOptions);
   106	    if (request.type === "staged") {
   107	      const indexSha = await gitText(repositoryRoot, ["write-tree"], processOptions);
   108	      return { type: request.type, baseRef, baseSha, indexSha };
   109	    }
   110	    return { type: request.type, baseRef, baseSha };
   111	  }
   112	
   113	  const match = request.expression.match(/^(.+?)(\.\.\.?)(.+)$/);
   114	  if (!match) throw new Error(`Invalid range '${request.expression}'. Use base..compare or base...compare.`);
   115	  const [, baseRef, operator, compareRef] = match;
   116	  if (!baseRef || !compareRef || !operator) throw new Error(`Invalid range '${request.expression}'.`);
   117	  validateRef(baseRef);
   118	  validateRef(compareRef);
   119	  const resolvedBase = operator === "..."
   120	    ? await gitText(repositoryRoot, ["merge-base", baseRef, compareRef], processOptions)
   121	    : await gitText(repositoryRoot, ["rev-parse", "--verify", baseRef], processOptions);
   122	  const compareSha = await gitText(repositoryRoot, ["rev-parse", "--verify", compareRef], processOptions);
   123	  return {
   124	    type: "range",
   125	    expression: request.expression,
   126	    baseRef,
   127	    compareRef,
   128	    baseSha: resolvedBase,
   129	    compareSha,
   130	    mergeBase: operator === "...",
   131	  };
   132	}
