   134	async function listChangedPaths(repositoryRoot: string, scope: ChangedScope, processOptions: ProcessOptions): Promise<ChangedPath[]> {
   135	  const args = ["diff", "--name-status", "-z", "--find-renames"];
   136	  if (scope.type === "staged") {
   137	    if (scope.indexSha) args.push(scope.baseSha, scope.indexSha);
   138	    else args.push("--cached", scope.baseSha);
   139	  }
   140	  else if (scope.type === "worktree") args.push(scope.baseSha);
   141	  else if (scope.type === "range") args.push(scope.baseSha, scope.compareSha);
   142	
   143	  const records = parseNameStatus(await gitBuffer(repositoryRoot, args, processOptions));
   144	  if (scope.type === "worktree") {
   145	    const untracked = splitNull(await gitBuffer(repositoryRoot, ["ls-files", "--others", "--exclude-standard", "-z"], processOptions));
   146	    const existing = new Set(records.map((record) => record.filePath));
   147	    for (const filePath of untracked) {
   148	      assertSafeRepositoryPath(filePath);
   149	      if (!existing.has(filePath)) records.push({ status: "added", filePath, oldPath: null });
   150	    }
   151	  }
   152	  return records;
   153	}
