   155	async function captureChangedScope(
   156	  repositoryRoot: string,
   157	  scope: ChangedScope,
   158	  limits: CaptureLimits,
   159	  options: CaptureOptions,
   160	  processOptions: ProcessOptions,
   161	): Promise<{
   162	  files: CapturedFile[];
   163	  skipped: Array<{ filePath: string; reason: string }>;
   164	  changedPaths: ChangedPath[];
   165	}> {
   166	  options.onProgress?.({ phase: "discover", current: 0, total: 0 });
   167	  const changedPaths = await listChangedPaths(repositoryRoot, scope, processOptions);
   168	  const files: CapturedFile[] = [];
   169	  const skipped: Array<{ filePath: string; reason: string }> = [];
   170	  let totalBytes = 0;
   171	
   172	  for (const [index, changedPath] of changedPaths.entries()) {
   173	    if (options.signal?.aborted) throw new Error("Diffpanel capture was cancelled.");
   174	    options.onProgress?.({ phase: "capture", current: index + 1, total: changedPaths.length, filePath: changedPath.filePath });
   175	    if (index >= limits.maxFiles) {
   176	      skipped.push({ filePath: changedPath.filePath, reason: `capture file limit ${limits.maxFiles} reached` });
   177	      continue;
   178	    }
   179	    const captured = await captureChangedFile(repositoryRoot, scope, changedPath, limits, processOptions);
   180	    if ("reason" in captured) {
   181	      skipped.push({ filePath: changedPath.filePath, reason: captured.reason });
   182	      continue;
   183	    }
   184	    const capturedBytes = (captured.beforeContent?.length ?? 0) + (captured.afterContent?.length ?? 0);
   185	    if (totalBytes + capturedBytes > limits.maxTotalBytes) {
   186	      skipped.push({ filePath: changedPath.filePath, reason: `capture content limit ${limits.maxTotalBytes} bytes reached` });
   187	      continue;
   188	    }
   189	    totalBytes += capturedBytes;
   190	    files.push(captured);
   191	  }
