   193	  if (files.length === 0) {
   194	    const detail = skipped.length > 0 ? ` (${skipped.length} unsupported files were skipped)` : "";
   195	    throw new Error(`No reviewable changes found${detail}. Use --repo for a repository snapshot.`);
   196	  }
   197	  return { files, skipped, changedPaths };
