  const output = path.join(appDirectory, `diffpanel-${manifest.version}.vsix`);
  await run(binary, ["package", "--no-dependencies", "--allow-missing-repository", "--out", output], stagingDirectory);
  process.stdout.write(`${output}\n`);
} finally {
  await rm(stagingDirectory, { recursive: true, force: true });
}

async function run(command, args, cwd) {
  await new Promise((resolve, reject) => {
    const child = spawn(command, args, { cwd, stdio: "inherit" });
    child.on("error", reject);
    child.on("close", (code) => code === 0 ? resolve() : reject(new Error(`${command} exited with ${code ?? -1}`)));
  });
}
# @diffpanel/git

Bounded, cancellation-aware Git capture for Diffpanel worktree, staged,
commit-range, and repository snapshots.

```ts
import { captureReview } from "@diffpanel/git";

const capture = await captureReview(
  { kind: "worktree", repoPath: process.cwd() },
  { signal: AbortSignal.timeout(30_000) },
);
```

Capture follows neither repository-relative traversal nor worktree symlinks,
enforces configurable file/output budgets, and retries mutable worktree reads
when the snapshot changes during capture. Requires Node.js 22.13 or newer.
# @diffpanel/storage

SQLite metadata and immutable content-addressed storage for Diffpanel review
runs.

```ts
import { DiffpanelStore } from "@diffpanel/storage";

const store = DiffpanelStore.open("/path/to/diffpanel-home");
const page = store.listRunsPage({ limit: 50 });
store.close();
```

The store provides stable cursor pagination, run-scoped blob authorization,
retention and garbage collection, and interrupted-publish recovery. Requires
Node.js 22.13 or newer.
